// Enrichment: validate, dry_run and schema lookups for one call, in parallel.
// Pure apart from the `call` handed in (register.tsx passes $.mcp.call), so
// it is tested in plain Node with canned Agent Services answers.
//
// Only read-only Agent Services tools are ever called: search, introspect, validate,
// dry_run. Every failure leaves its facts unknown; nothing is assumed.

import type { McpToolResult } from 'claude-code'

import { annotate } from './annotate.ts'
import type { Enrichment } from './annotate.ts'
import { depthOf, provisionalService } from './build.ts'
import { accessOf, payloadOf, scopeFor, sdlOf, validationOf } from './gas.ts'
import type { Access, Validation } from './gas.ts'
import type { CallIR, CheckOutcome, Checks, FieldIR } from './ir.ts'
import { indexSdl } from './schema.ts'
import type { SchemaIndex } from './schema.ts'
import { subOperation, unique } from './split.ts'

export type GasTool = 'search' | 'introspect' | 'validate' | 'dry_run'
export type CallGas = (tool: GasTool, args: Record<string, unknown>) => Promise<McpToolResult>

/**
 * What enrichment remembers between calls. Everything in it is valid for one
 * bundleDigest: a result carrying another digest clears it (schema or policy moved).
 */
export type EnrichCache = {
  bundleDigest?: string
  scopes?: string[]
  /** `scope\nrootField` → SDL of the root field's `type Query { … }` snippet. */
  roots: Map<string, string[]>
  /** `scope\ntype\ndepth` → SDL strings. */
  types: Map<string, string[]>
}

export const emptyCache = (): EnrichCache => ({ roots: new Map(), types: new Map() })

function noteDigest(cache: EnrichCache, digest: string | undefined): void {
  if (digest === undefined || digest === cache.bundleDigest) return
  if (cache.bundleDigest !== undefined) {
    cache.scopes = undefined
    cache.roots.clear()
    cache.types.clear()
  }
  cache.bundleDigest = digest
}

async function read(call: CallGas, cache: EnrichCache, tool: GasTool, args: Record<string, unknown>) {
  const payload = payloadOf(await call(tool, args))
  if (!payload.ok) throw new Error(`${tool}: ${payload.error}`)
  noteDigest(cache, payload.bundleDigest)
  return payload.value
}

export async function scopesOf(call: CallGas, cache: EnrichCache): Promise<string[]> {
  if (cache.scopes !== undefined) return cache.scopes
  const value = await read(call, cache, 'search', { terms: [] })
  const scopes = Array.isArray(value.scopes) ? value.scopes.filter((one): one is string => typeof one === 'string') : []
  cache.scopes = scopes
  return scopes
}

/** The root field's signature: search finds `type Query { field(…): T }` with its description. */
async function rootSdl(call: CallGas, cache: EnrichCache, scope: string, field: string, opType: string): Promise<string[]> {
  const key = `${scope}\n${field}`
  const cached = cache.roots.get(key)
  if (cached !== undefined) return cached
  const value = await read(call, cache, 'search', {
    terms: [field],
    scope,
    ...(opType === 'subscription' ? {} : { operationType: opType }),
  })
  const results = Array.isArray(value.results) ? value.results : []
  const hit = results.find(
    (one): one is { operationName: string; types: unknown[] } =>
      typeof one === 'object' && one !== null && (one as { operationName?: unknown }).operationName === field,
  )
  const sdl = hit === undefined ? [] : hit.types.filter((one): one is string => typeof one === 'string')
  cache.roots.set(key, sdl)
  return sdl
}

async function typeSdl(call: CallGas, cache: EnrichCache, scope: string, type: string, depth: number): Promise<string[]> {
  const key = `${scope}\n${type}\n${depth}`
  const cached = cache.types.get(key)
  if (cached !== undefined) return cached
  const sdl = sdlOf(await read(call, cache, 'introspect', { scope, type, depth }))
  cache.types.set(key, sdl)
  return sdl
}

const ROOT_TYPE = { query: 'Query', mutation: 'Mutation', subscription: 'Subscription' } as const
type OpKind = keyof typeof ROOT_TYPE

/** Indexes the SDL of one scope's `roots` into `index`, which may already hold other scopes' types. */
async function schemaOf(call: CallGas, cache: EnrichCache, opType: OpKind, roots: readonly FieldIR[], scope: string, index: SchemaIndex): Promise<void> {
  await Promise.all(
    roots.map(async root => {
      indexSdl(await rootSdl(call, cache, scope, root.name, opType), index)
      const def = index.get(ROOT_TYPE[opType])?.get(root.name)
      if (def === undefined || root.children.length === 0) return
      indexSdl(await typeSdl(call, cache, scope, def.namedType, Math.max(1, depthOf(root.children) + 1)), index)
    }),
  )
}

const CHECKS = ['policy', 'validation', 'schema'] as const

/** What one scope's checks found. */
type ScopeResult = { validation?: Validation; access?: Access; isSchemaRead: boolean; checks: Checks }

const SEVERITY: CheckOutcome[] = ['ok', 'skipped', 'not-allowed', 'failed']
const worse = (a: CheckOutcome, b: CheckOutcome): CheckOutcome => (SEVERITY.indexOf(b) > SEVERITY.indexOf(a) ? b : a)

/** Runs validate, dry_run and the schema lookups for the roots of one scope; never rejects. */
async function checkScope(
  call: CallGas,
  cache: EnrichCache,
  opType: OpKind,
  scope: string,
  roots: readonly FieldIR[],
  operation: string | undefined,
  index: SchemaIndex,
): Promise<ScopeResult> {
  const checks: Checks = { policy: 'ok', validation: 'ok', schema: 'ok' }
  /** A failure leaves its facts unknown and records why: not allowed by the user's rules, or an Agent Services error. */
  const settled = <T>(work: Promise<T>, which: readonly (typeof CHECKS)[number][]): Promise<T | undefined> =>
    work.catch((error: unknown) => {
      const isNotAllowed = typeof error === 'object' && error !== null && 'decision' in error
      for (const key of which) checks[key] = isNotAllowed ? 'not-allowed' : 'failed'
      if (!isNotAllowed && checks.error === undefined) checks.error = String(error instanceof Error ? error.message : error).slice(0, 160)
      return undefined
    })
  // The schema is read from the root fields alone; only validate and dry_run need the operation.
  const schema = settled(schemaOf(call, cache, opType, roots, scope, index).then(() => true), ['schema'])
  if (operation === undefined) {
    // The sub-operation could not be built: this scope's roots stay unchecked.
    checks.policy = 'skipped'
    checks.validation = 'skipped'
    return { isSchemaRead: (await schema) === true, checks }
  }
  const [validation, access, isSchemaRead] = await Promise.all([
    settled(read(call, cache, 'validate', { scope, operation }).then((value): Validation => validationOf(value)), ['validation']),
    settled(
      read(call, cache, 'dry_run', { requests: [{ scope, operation }] }).then((value): Access => {
        const results = Array.isArray(value.results) ? value.results : []
        const first: unknown = results[0]
        // Agent Services reports a per-request failure as `{ errors: [string] }` (e.g. `Unknown scope "glean"`).
        const errors = typeof first === 'object' && first !== null && Array.isArray((first as { errors?: unknown }).errors) ? (first as { errors: unknown[] }).errors : []
        if (typeof errors[0] === 'string') throw new Error(`dry_run: ${errors[0]}`)
        const found = accessOf(first)
        if (found === undefined) throw new Error('dry_run: no result')
        return found
      }),
      ['policy'],
    ),
    schema,
  ])
  return { ...(validation !== undefined && { validation }), ...(access !== undefined && { access }), isSchemaRead: isSchemaRead === true, checks }
}

/**
 * Enriches `ir` (built from `operation`). Roots are grouped by service scope
 * and each scope is checked on its own, as a sub-operation of just its roots
 * (src/split.ts), all scopes in parallel; the answers merge back into the one
 * IR. A root no scope claims keeps its facts unknown. Resolves once every
 * source has answered or failed; never rejects.
 */
export async function enrich(call: CallGas, cache: EnrichCache, ir: CallIR, operation: string, variables: Record<string, unknown> = {}): Promise<CallIR> {
  if (ir.state === 'unparseable') return ir
  // Nothing to look up; never leave a call `analyzing`, or the pump retries it forever.
  if (ir.roots.length === 0 || ir.opType === undefined) return { ...ir, state: 'partial' }
  const opType = ir.opType

  let scopes: string[] | undefined
  const lookup: Checks = { policy: 'ok', validation: 'ok', schema: 'ok' }
  try {
    scopes = await scopesOf(call, cache)
  } catch (error) {
    const isNotAllowed = typeof error === 'object' && error !== null && 'decision' in error
    const outcome: CheckOutcome = isNotAllowed ? 'not-allowed' : 'failed'
    for (const key of CHECKS) lookup[key] = outcome
    if (!isNotAllowed) lookup.error = String(error instanceof Error ? error.message : error).slice(0, 160)
  }
  const digest = cache.bundleDigest === undefined ? {} : { bundleDigest: cache.bundleDigest }
  if (scopes === undefined) return annotate(ir, { isIncomplete: true, checks: lookup, ...digest })

  const known = scopes
  const scopeOf = (root: FieldIR) => scopeFor(root.name, known)
  const groups = new Map<string, FieldIR[]>()
  for (const root of ir.roots) {
    const scope = scopeOf(root)
    if (scope !== undefined) groups.set(scope, [...(groups.get(scope) ?? []), root])
  }
  const hasUnclaimed = ir.roots.some(root => scopeOf(root) === undefined)
  // One scope claiming every root checks the operation as sent.
  const isWhole = groups.size === 1 && !hasUnclaimed
  const index: SchemaIndex = new Map()
  const results = await Promise.all(
    [...groups].map(async ([scope, roots]): Promise<ScopeResult> => {
      const names = new Set(roots.map(root => root.name))
      const sub = isWhole ? operation : subOperation(operation, variables, field => names.has(field))?.operation
      return checkScope(call, cache, opType, scope, roots, sub, index)
    }),
  )

  const checks: Checks = { policy: 'ok', validation: 'ok', schema: 'ok' }
  for (const result of results) {
    for (const key of CHECKS) checks[key] = worse(checks[key], result.checks[key])
    if (checks.error === undefined && result.checks.error !== undefined) checks.error = result.checks.error
  }
  // A root no scope claims is not checked at all.
  if (hasUnclaimed) for (const key of CHECKS) checks[key] = worse(checks[key], 'skipped')

  // Valid only when every scope validated and none was left out; any invalid scope makes the call invalid.
  const validations = results.flatMap(result => (result.validation === undefined ? [] : [result.validation]))
  const validation: Validation | undefined = validations.some(one => !one.valid)
    ? { valid: false, diagnostics: validations.flatMap(one => one.diagnostics) }
    : validations.length === results.length && !hasUnclaimed
      ? { valid: true, diagnostics: [] }
      : undefined
  const accesses = results.flatMap(result => (result.access === undefined ? [] : [result.access]))
  const access: Access | undefined =
    accesses.length === 0
      ? undefined
      : { denyOperation: accesses.some(one => one.denyOperation), fields: new Map(accesses.flatMap(one => [...one.fields])) }
  // Each service once in the order its first root appears; an unclaimed root by its name prefix.
  const services = unique(ir.roots.flatMap(root => scopeOf(root) ?? provisionalService(root.name) ?? []))
  const first = ir.roots[0]
  const firstScope = first === undefined ? undefined : scopeOf(first)

  const found: Enrichment = {
    isIncomplete: CHECKS.some(key => checks[key] !== 'ok'),
    checks,
    services,
    rootScopes: new Map(ir.roots.flatMap(root => {
      const scope = scopeOf(root)
      return scope === undefined ? [] : [[root.path, scope] as const]
    })),
    ...(firstScope !== undefined && { scope: firstScope }),
    ...digest,
    ...(validation !== undefined && { validation }),
    ...(access !== undefined && { access }),
    ...(results.some(result => result.isSchemaRead) && { schema: index }),
  }
  return annotate(ir, found)
}

files.src/normalize.ts:
// Normalizes an Agent Services `execute` operation into what will actually run: one
// operation, fragments inlined, @skip/@include applied, aliases resolved to
// real field names, variables substituted. Pure; never throws.
//
// The operation comes from a model that may be prompt-injected, so every
// ambiguity resolves toward showing more (keep a field whose condition is
// unknown) or refusing (duplicate fragment names, duplicate input keys).

import { parse, print, Kind } from './vendor/graphql.js'
import type {
  ArgumentNode,
  DirectiveNode,
  DocumentNode,
  FieldNode,
  FragmentDefinitionNode,
  InlineFragmentNode,
  OperationDefinitionNode,
  SelectionNode,
  SelectionSetNode,
  ValueNode,
} from './vendor/graphql.js'

export type ArgValue = { name: string; value: unknown; fromVariable: boolean; variable?: string }
export type NormalizedField = {
  /** The REAL field name, never the alias. */
  name: string
  /** Kept only for the raw view. */
  alias?: string
  /** Type condition it was selected under (inline fragment or fragment's typeCondition), if any. */
  onType?: string
  args: ArgValue[]
  /** Directive names other than skip/include; unknown ones kept. */
  directives: string[]
  children: NormalizedField[]
}
export type NormalizeFailure =
  | 'unparseable'
  | 'no-operation'
  | 'multiple-operations'
  | 'fragment-cycle'
  | 'unknown-fragment'
  | 'too-large'
export type Normalized =
  | {
      ok: true
      opType: 'query' | 'mutation' | 'subscription'
      opName?: string
      roots: NormalizedField[]
      variables: Record<string, unknown>
      printed: string
    }
  | { ok: false; reason: NormalizeFailure; message: string }

/** Most fields the expanded operation may contain. */
export const MAX_FIELDS = 5000
/** Deepest field nesting allowed (a root field is depth 1). */
export const MAX_DEPTH = 64
/**
 * Most selections (fields, spreads, inline fragments, skipped or not) the
 * expansion may visit. Bounds work for fan-out bombs whose leaves are all
 * skipped, which would never trip MAX_FIELDS.
 */
export const MAX_VISITS = 20000
/** Deepest fragment / inline-fragment / field nesting combined. */
export const MAX_NESTING = 128
/** Parser token cap; a larger document is reported as too-large. */
export const MAX_TOKENS = 100000

class Fail {
  reason: NormalizeFailure
  message: string
  constructor(reason: NormalizeFailure, message: string) {
    this.reason = reason
    this.message = message
  }
}

const hasOwn = (o: object, k: string): boolean => Object.prototype.hasOwnProperty.call(o, k)

/** Assigns without invoking setters such as `__proto__`. */
function put(o: Record<string, unknown>, k: string, v: unknown): void {
  Object.defineProperty(o, k, { value: v, enumerable: true, writable: true, configurable: true })
}

type Converted = { value: unknown; fromVariable: boolean }

function convertValue(node: ValueNode, vars: Record<string, unknown>): Converted {
  switch (node.kind) {
    case Kind.VARIABLE: {
      const name = node.name.value
      return { value: hasOwn(vars, name) ? vars[name] : undefined, fromVariable: true }
    }
    case Kind.INT: {
      const n = Number(node.value)
      // Out-of-range ints keep their exact source text rather than a rounded
      // number that would show a different value from the one sent.
      return { value: Number.isSafeInteger(n) ? n : node.value, fromVariable: false }
    }
    case Kind.FLOAT: {
      const n = Number(node.value)
      return { value: Number.isFinite(n) ? n : node.value, fromVariable: false }
    }
    case Kind.STRING:
    case Kind.ENUM:
      return { value: node.value, fromVariable: false }
    case Kind.BOOLEAN:
      return { value: node.value, fromVariable: false }
    case Kind.NULL:
      return { value: null, fromVariable: false }
    case Kind.LIST: {
      let fromVariable = false
      const value = node.values.map((v) => {
        const c = convertValue(v, vars)
        if (c.fromVariable) fromVariable = true
        return c.value
      })
      return { value, fromVariable }
    }
    case Kind.OBJECT: {
      let fromVariable = false
      const value: Record<string, unknown> = {}
      for (const f of node.fields) {
        const key = f.name.value
        if (hasOwn(value, key)) {
          // A JS object can show only one of the two; refuse instead of guessing.
          throw new Fail('unparseable', `Input object has duplicate field "${key}"`)
        }
        const c = convertValue(f.value, vars)
        if (c.fromVariable) fromVariable = true
        put(value, key, c.value)
      }
      return { value, fromVariable }
    }
    default:
      throw new Fail('unparseable', `Unsupported value kind ${(node as { kind: string }).kind}`)
  }
}

function convertArgs(args: readonly ArgumentNode[] | undefined, vars: Record<string, unknown>): ArgValue[] {
  const out: ArgValue[] = []
  for (const a of args ?? []) {
    const c = convertValue(a.value, vars)
    const arg: ArgValue = { name: a.name.value, value: c.value, fromVariable: c.fromVariable }
    if (a.value.kind === Kind.VARIABLE) arg.variable = a.value.name.value
    out.push(arg)
  }
  return out
}

type Condition = 'drop' | 'keep' | 'unknown'

/** Evaluates one @skip/@include `if:`. 'unknown' when it cannot be decided. */
function conditionOf(d: DirectiveNode, vars: Record<string, unknown>): Condition {
  const ifArg = (d.arguments ?? []).filter((a) => a.name.value === 'if')
  const only = ifArg.length === 1 ? ifArg[0] : undefined
  if (!only) return 'unknown'
  const v = only.value
  let b: unknown
  if (v.kind === Kind.BOOLEAN) b = v.value
  else if (v.kind === Kind.VARIABLE) b = hasOwn(vars, v.name.value) ? vars[v.name.value] : undefined
  else return 'unknown'
  if (typeof b !== 'boolean') return 'unknown'
  const isSkip = d.name.value === 'skip'
  return (isSkip ? b : !b) ? 'drop' : 'keep'
}

/**
 * Applies @skip/@include. Returns null when the selection is dropped, else the
 * directives to print: decided skip/include removed, undecided ones kept so
 * the printed view shows the field is conditional.
 */
function applyConditions(
  directives: readonly DirectiveNode[] | undefined,
  vars: Record<string, unknown>,
): DirectiveNode[] | null {
  const kept: DirectiveNode[] = []
  let drop = false
  for (const d of directives ?? []) {
    const n = d.name.value
    if (n === 'skip' || n === 'include') {
      const c = conditionOf(d, vars)
      if (c === 'drop') drop = true
      else if (c === 'unknown') kept.push(d)
    } else {
      kept.push(d)
    }
  }
  return drop ? null : kept
}

function otherDirectiveNames(directives: readonly DirectiveNode[]): string[] {
  return directives.map((d) => d.name.value).filter((n) => n !== 'skip' && n !== 'include')
}

type Ctx = {
  fragments: Map<string, FragmentDefinitionNode>
  vars: Record<string, unknown>
  fields: number
  visits: number
}

type Expanded = { fields: NormalizedField[]; selections: SelectionNode[] }

const argsKey = (field: NormalizedField): string => JSON.stringify([...field.args].sort((a, b) => a.name.localeCompare(b.name)).map(arg => [arg.name, arg.value]))

/**
 * GraphQL field merging: siblings with one response key (`alias ?? name`), one
 * real name, one type condition and the same arguments are one field, their
 * selections joined (`issues { ...A ...B }` with `A { key }` and `B { key
 * summary }` selects `key summary`). Siblings that differ in arguments are not
 * merged: the call is invalid, and both stay in view.
 */
function merged(fields: readonly NormalizedField[]): NormalizedField[] {
  const out: NormalizedField[] = []
  const first = new Map<string, NormalizedField>()
  for (const field of fields) {
    const id = [field.alias ?? field.name, field.name, field.onType ?? '', argsKey(field)].join('\u0000')
    const into = first.get(id)
    if (into === undefined) {
      first.set(id, field)
      out.push(field)
      continue
    }
    into.children = merged([...into.children, ...field.children])
    into.directives = [...new Set([...into.directives, ...field.directives])]
  }
  return out
}

function expand(
  set: SelectionSetNode,
  ctx: Ctx,
  onType: string | undefined,
  depth: number,
  nesting: number,
  stack: string[],
): Expanded {
  if (nesting > MAX_NESTING) throw new Fail('too-large', `Selections nest deeper than ${MAX_NESTING}`)
  const fields: NormalizedField[] = []
  const selections: SelectionNode[] = []
  for (const sel of set.selections) {
    if (++ctx.visits > MAX_VISITS) {
      throw new Fail('too-large', `Operation expands to more than ${MAX_VISITS} selections`)
    }
    const kept = applyConditions(sel.directives, ctx.vars)
    if (kept === null) continue

    if (sel.kind === Kind.FIELD) {
      const fieldDepth = depth + 1
      if (fieldDepth > MAX_DEPTH) throw new Fail('too-large', `Fields nest deeper than ${MAX_DEPTH}`)
      if (++ctx.fields > MAX_FIELDS) {
        throw new Fail('too-large', `Operation expands to more than ${MAX_FIELDS} fields`)
      }
      const nf: NormalizedField = {
        name: sel.name.value,
        args: convertArgs(sel.arguments, ctx.vars),
        directives: otherDirectiveNames(kept),
        children: [],
      }
      if (sel.alias) nf.alias = sel.alias.value
      if (onType !== undefined) nf.onType = onType
      let childSet: SelectionSetNode | undefined
      if (sel.selectionSet) {
        // Children of a field start a fresh type scope.
        const sub = expand(sel.selectionSet, ctx, undefined, fieldDepth, nesting + 1, stack)
        nf.children = sub.fields
        childSet = { kind: Kind.SELECTION_SET, selections: sub.selections }
      }
      fields.push(nf)
      const printedField: FieldNode = {
        kind: Kind.FIELD,
        alias: sel.alias,
        name: sel.name,
        arguments: sel.arguments,
        directives: kept,
        selectionSet: childSet,
      }
      selections.push(printedField)
      continue
    }

    let typeName: string | undefined
    let typeCondition: InlineFragmentNode['typeCondition']
    let body: SelectionSetNode
    let nextStack = stack
    if (sel.kind === Kind.FRAGMENT_SPREAD) {
      const name = sel.name.value
      if (stack.includes(name)) {
        throw new Fail('fragment-cycle', `Fragment cycle: ${[...stack, name].join(' -> ')}`)
      }
      const frag = ctx.fragments.get(name)
      if (!frag) throw new Fail('unknown-fragment', `Unknown fragment "${name}"`)
      typeCondition = frag.typeCondition
      typeName = frag.typeCondition.name.value
      body = frag.selectionSet
      nextStack = [...stack, name]
    } else {
      typeCondition = sel.typeCondition
      typeName = sel.typeCondition ? sel.typeCondition.name.value : onType
      body = sel.selectionSet
    }
    const sub = expand(body, ctx, typeName, depth, nesting + 1, nextStack)
    fields.push(...sub.fields)
    if (sub.selections.length > 0) {
      const inline: InlineFragmentNode = {
        kind: Kind.INLINE_FRAGMENT,
        typeCondition,
        directives: kept,
        selectionSet: { kind: Kind.SELECTION_SET, selections: sub.selections },
      }
      selections.push(inline)
    }
  }
  return { fields: merged(fields), selections }
}

function run(operation: string, given: Record<string, unknown>): Normalized {
  if (typeof operation !== 'string') {
    return { ok: false, reason: 'unparseable', message: 'Operation is not a string' }
  }
  let doc: DocumentNode
  try {
    doc = parse(operation, { noLocation: true, maxTokens: MAX_TOKENS })
  } catch (e) {
    const message = e instanceof Error ? e.message : String(e)
    if (/^Syntax Error: Document contains more th[ae]t? /.test(message)) {
      return { ok: false, reason: 'too-large', message }
    }
    return { ok: false, reason: 'unparseable', message }
  }

  const ops: OperationDefinitionNode[] = []
  const fragments = new Map<string, FragmentDefinitionNode>()
  for (const def of doc.definitions) {
    if (def.kind === Kind.OPERATION_DEFINITION) ops.push(def)
    else if (def.kind === Kind.FRAGMENT_DEFINITION) {
      const name = def.name.value
      if (fragments.has(name)) {
        return { ok: false, reason: 'unparseable', message: `Fragment "${name}" is defined more than once` }
      }
      fragments.set(name, def)
    } else {
      return { ok: false, reason: 'unparseable', message: `Unexpected ${def.kind} in an executable document` }
    }
  }
  const op = ops[0]
  if (!op) return { ok: false, reason: 'no-operation', message: 'Document has no operation' }
  if (ops.length > 1) {
    return {
      ok: false,
      reason: 'multiple-operations',
      message: `Document has ${ops.length} operations; Agent Services runs one per call`,
    }
  }

  const vars: Record<string, unknown> = {}
  const src = given !== null && typeof given === 'object' && !Array.isArray(given) ? given : {}
  for (const k of Object.keys(src)) put(vars, k, src[k])
  for (const vd of op.variableDefinitions ?? []) {
    const name = vd.variable.name.value
    if (vd.defaultValue && (!hasOwn(vars, name) || vars[name] === undefined)) {
      put(vars, name, convertValue(vd.defaultValue, {}).value)
    }
  }

  const ctx: Ctx = { fragments, vars, fields: 0, visits: 0 }
  const top = expand(op.selectionSet, ctx, undefined, 0, 0, [])

  const printedOp: OperationDefinitionNode = {
    kind: Kind.OPERATION_DEFINITION,
    operation: op.operation,
    name: op.name,
    variableDefinitions: op.variableDefinitions,
    directives: op.directives,
    selectionSet: { kind: Kind.SELECTION_SET, selections: top.selections },
  }
  const printed = print({ kind: Kind.DOCUMENT, definitions: [printedOp] })

  const result: Normalized = {
    ok: true,
    opType: op.operation as 'query' | 'mutation' | 'subscription',
    roots: top.fields,
    variables: vars,
    printed,
  }
  if (op.name) result.opName = op.name.value
  return result
}

export function normalize(operation: string, variables: Record<string, unknown>): Normalized {
  try {
    return run(operation, variables)
  } catch (e) {
    if (e instanceof Fail) return { ok: false, reason: e.reason, message: e.message }
    const message = e instanceof Error ? `${e.name}: ${e.message}` : String(e)
    return { ok: false, reason: 'unparseable', message }
  }
}

